arguments.command:
cd /tmp/mainwt && git fetch -q origin main && git checkout -q FETCH_HEAD; for s in 82e93be8 220411da fe97927d f631f56f 8cc5b0cd bd1b6b35 75bce959; do f=$(grep -l "$s" S01/*.md 2>/dev/null | head -1); if [ -n "$f" ]; then # compare utterance text with the source commit
 line=$(awk -v sha="$s" 'index($0,sha){found=1;next} found && /^$/{next} found && !/^\*\*/{print; exit}' "$f"); 
 src=$(git show $s | tail -1); 
 if [ "$line" = "$src" ]; then echo "$s OK in $f"; else echo "$s MISMATCH in $f"; echo "  main: $line"; echo "  src : $src"; fi
 else echo "$s NOT YET RECORDED"; fi; done
